-- STAGING only: simulated COBRA YA loans, secure idempotent schedules.
alter table public.cy_loans add column if not exists demo_request_id uuid;
create unique index if not exists cy_loans_demo_request_unique on public.cy_loans(demo_request_id) where demo_request_id is not null;
CREATE OR REPLACE FUNCTION public.cc_clan_cobra_create_demo_loan(p_user_id uuid, p_client_id uuid, p_request_id uuid, p_principal numeric, p_interest_percent numeric, p_installments integer, p_first_due date)\n RETURNS uuid\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\ndeclare\n v_old public.cy_loans%rowtype;\n v_loan_id uuid;\n v_total numeric(14,2);\n v_regular numeric(14,2);\n v_payment numeric(14,2);\n v_n integer;\nbegin\n if current_user<>'service_role' then raise exception 'Server-only loan demo';end if;\n if p_user_id is null or p_client_id is null or p_request_id is null\n  or p_principal is null or p_principal<>round(p_principal,2)\n  or p_principal<10 or p_principal>10000\n  or p_interest_percent is null or p_interest_percent<>round(p_interest_percent,2)\n  or p_interest_percent<0 or p_interest_percent>100\n  or p_installments is null or p_installments not between 1 and 12\n  or p_first_due is null or p_first_due<=current_date\n  or p_first_due>current_date+365\n then raise exception 'Invalid demo loan parameters';end if;\n perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(\n   'clan-cobra-demo-loan:'||p_request_id::text,0));\n select * into v_old from public.cy_loans where demo_request_id=p_request_id;\n if found then\n  if v_old.owner_id<>p_user_id or v_old.client_id<>p_client_id\n    or v_old.principal<>p_principal\n    or v_old.interest_rate<>p_interest_percent\n    or v_old.term_installments<>p_installments\n    or v_old.first_due_on<>p_first_due\n    or v_old.currency<>'PEN'\n  then raise exception 'Demo loan request key reused with different details';end if;\n  return v_old.id;\n end if;\n if not exists(select 1 from public.cc_clan_cobra_access_periods\n  where user_id=p_user_id and starts_at<=now() and ends_at>now()) then\n  raise exception 'Active COBRA YA access required';\n end if;\n if not exists(select 1 from public.cy_clients\n  where id=p_client_id and owner_id=p_user_id and alias='DEMO') then\n  raise exception 'Only own fictitious clients are permitted';\n end if;\n v_total:=round(p_principal*(1+p_interest_percent/100),2);\n v_regular:=trunc(v_total/p_installments,2);\n insert into public.cy_loans(\n  owner_id,client_id,principal,interest_rate,term_installments,first_due_on,\n  currency,calculation_method,total_due,demo_request_id\n ) values(\n  p_user_id,p_client_id,p_principal,p_interest_percent,p_installments,p_first_due,\n  'PEN','FLAT_SIMPLE',v_total,p_request_id\n ) returning id into v_loan_id;\n for v_n in 1..p_installments loop\n  v_payment:=case when v_n=p_installments\n    then v_total-v_regular*(p_installments-1) else v_regular end;\n  insert into public.cy_installments(\n    loan_id,owner_id,installment_number,due_on,amount,paid_total,status\n  ) values(\n    v_loan_id,p_user_id,v_n,\n    (p_first_due+pg_catalog.make_interval(months=>(v_n-1)))::date,\n    v_payment,0,'PENDING'\n  );\n end loop;\n if (select count(*) from public.cy_installments\n    where loan_id=v_loan_id and owner_id=p_user_id)<>p_installments\n then raise exception 'Incomplete demo schedule';end if;\n return v_loan_id;\nend $function$\n
revoke all on function public.cc_clan_cobra_create_demo_loan(uuid,uuid,uuid,numeric,numeric,integer,date) from public,anon,authenticated;
grant execute on function public.cc_clan_cobra_create_demo_loan(uuid,uuid,uuid,numeric,numeric,integer,date) to service_role;
